Translate the following MS C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#define use_crt_defines
#define _ert_No_deprecate

#include <cstdio>
#include <algorithm>
using namespace std;

long long gcd(long long a, long long b) {
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

int main() {
    long long x, y, n;
    scanf("%lld %lld %lld", &x, &y, &n);
    long long best_num = 50, best_den = 1;
    long long best_r = 0, best_i = 1;
    long long i = 1;
    do {
        long long prod = x * i;
        long long r = prod / y;
        long long rem = prod % y;
        if (rem > y / 2) {
            r++;
            rem = y - rem;
        }
        long long err_num = rem;
        long long err_den = i * y;
        if (err_num * best_den < best_num * err_den) {
            best_num = err_num;
            best_den = err_den;
            best_r = r;
            best_i = i;
        }
        i++;
    } while (i <= n);
    printf("%lld/%lld", best_r, best_i);
    return 0;
}
